`,a.jsx(j,{reference:"Luј Šnitser — austrijski orijentalist (umro 1893. godine)",children:a.jsx(i.p,{children:"Bio je zaprepašćen naukom o el-Džerhu ve et-Ta'dilu. Svaka ličnost koja je prenela nekoliko redova u islamskoj istoriji ima biografiju — znamo njeno rođenje i smrt, njene učitelje i učenike, njena putovanja — i imamo jasnu ocenu o ispravnosti te ličnosti i pouzdanosti njenih predaja. Desetine specijalizovanih knjiga u ovoj oblasti sadrže stotine hiljada biografija."})}),`
`,a.jsx(o,{src:"/ADAM-Wiki/images/hadis/28.webp",alt:"fo 38",caption:""}),`
`,a.jsx(e,{children:a.jsx(i.p,{children:"Ovaj arapski tekst citira austrijskog orijentalistu Luja Sprengera o muslimanskoj biografskoj kritici. Istaknuti odlomak kaže da među svim prethodnim narodima, pa čak i među savremenim narodima, ne postoji narod koji je proizveo išta slično Muslimanima u nauci o imenima i biografijama ljudi. Kaže da se ova velika i ozbiljna nauka bavi stanjem i prilikama oko pola miliona prenosilaca — pokazujući neuporediv obim muslimanske kritike prenosilaca."})}),`
`,a.jsx(i.h2,{children:"Učenjak 16 - Džejms Robinson — britanski orijentalist"}),`
`,a.jsx(j,{reference:"Džejms Robinson — britanski orijentalist (umro 2016. godine)",children:a.jsx(i.p,{children:"Izražava divljenje islamskoj metodi dokumentovanja i njenoj strogosti — priznajući da hiljade ljudi koji su prenosili Sunnet svaki ima sveobuhvatnu i preciznu biografiju koja uključuje njegovo puno ime, učitelje, učenike, naučna putovanja i naučne ocene o njima."})}),`
`,a.jsx(o,{src:"/ADAM-Wiki/images/hadis/29.webp",alt:"fo 39",caption:""}),`
`,a.jsx(e,{children:a.jsx(i.p,{children:"Ovaj mešoviti arapsko-engleski tekst predstavlja izjavu Džejmsa Robsona o lancu prenosilaca (isnadu) u muslimanskoj tradiciji, sa arapskim prevodom ispod. Istaknuti arapski deo kaže da je jedna od poznatih odlika arapske književnosti davanje lanca autoriteta za izjave o prošlosti. Objašnjava da ovaj lanac služi dokumentovanju na najstroži način, idealno dovodeći izveštaj nazad do neposrednog dokaza, i da je u hadisu isnad toliko važan da se predaja bez njega smatra bezvrednom."})}),`
`,a.jsx(i.h2,{children:"Učenjak 17 - Viljem A. Graham — oralna transmisija Kur'ana"}),`
`,a.jsx(j,{reference:"The Journal of Interdisciplinary History, Vol. 23, No. 3, Religion and History (Winter, 1993), pp. 495–522.",children:a.jsx(i.p,{children:"Rašireno pamćenje u grudima, i učenje i podučavanje Kur'ana od strane brojnih pobožnih, odanih i pouzdanih Muslimana u svakoj generaciji, može zaštititi božanski tekst od izobličavanja tekstova koje je zadesilo sve prethodne nadahnute knjige. Konačni razvoj sedam poznatih i prenošenih kur'anskih učenja, koja su prenošena usmeno, ostaje osnova i poreklo kur'anskog teksta i učenja koja su prihvaćena do današnjeg dana. Najbolji tekst Svetog Kur'ana u potpunosti se zasniva na ovim učenjima prenošenim usmeno putem neprekidnog prenošenja i ne oslanja se na rukopise iz prvih vekova Islama."})}),`
`,a.jsx(i.h2,{children:"Učenjak - Džonatan Braun - Nauka o hadisu u poređenju sa Istorijskim Kritičkim Metodom (IKM)"}),`
`,a.jsx(i.p,{children:"Džonatan Braun govori o ograničenjima, pristrasnostima i značajnim nedostacima zapadnog humanističkog i naturalističkog okvira Istorijsko-kritičke metode (IKM) [IKM je dominantni zapadni akademski pristup analizi drevnih verskih tekstova. Primenjuje sekularne pretpostavke, tretira čuda kao nemoguća i oslanja se na posrednu tekstualnu analizu, a ne na proverene lance prenošenja], koja stoji u oštroj suprotnosti sa transcendentalnim teističkim okvirom i tradicionalnim sunitskim razumevanjem hadisa."}),`
`,a.jsx(o,{src:"/ADAM-Wiki/images/hadis/30.webp",alt:"fo 33",caption:""}),`
`,a.jsx(o,{src:"/ADAM-Wiki/images/hadis/31.webp",alt:"fo 34",caption:""}),`
`,a.jsx(o,{src:"/ADAM-Wiki/images/hadis/32.webp",alt:"fo 35",caption:""}),`
`,a.jsx(i.h3,{children:"Zašto je nauka o hadisu mnogo superiornija od ICM"}),`
`,a.jsx(i.p,{children:"Sunitsko razumevanje hadisa nadmašuje IKM kroz svoju dubinsku, sistematsku analizu: fokusiranje na svaku pojedinačnu ličnost i lanac, odgovarajuće pomno ispitivanje sadržaja (matna) prilikom utvrđivanja preciznih i koherentnih verovanja i propisa, te sistematsku i proverljivu kritičku metodu — a ne naturalistički okvir opterećen pristrasnošću."}),`
`,a.jsx(o,{src:"/ADAM-Wiki/images/hadis/33.webp",alt:"fo 36",caption:""}),`
