`,a.jsx(i.h3,{children:"Kombinovanje onoga što je preneseno o zabrani i dozvoli:"}),`
`,a.jsx(i.p,{children:"Da hadisi dozvole poništavaju (abrogiraju) hadise zabrane, kao što je Ibn Hadžar preneo u El-Fethu, rekavši:"}),`
`,a.jsx(s,{children:'"Ili da je zabrana došla prva, a dozvola je poništava."'}),`
